<?php
require __DIR__ . '/backend/common.php'; require_admin(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$id=(int)input('id');$active=input('active')==='1'?1:0;$conn->execute_query("UPDATE users SET is_active=?,session_version=session_version+1 WHERE id=? AND role<>'admin'",[$active,$id]);flash('Account status updated.');go('admin-users.php');}catch(Throwable $e){$error=page_error($e);}}
$accounts=$conn->query('SELECT id,full_name,email,role,department,is_active,created_at FROM users ORDER BY created_at DESC LIMIT 100')->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>User Management · Admin</title><link rel="stylesheet" href="portal.css"></head><body class="portal-page"><div class="app-container portal-layout"><?php require __DIR__.'/backend/sidebar.php'; ?><main class="main-content"><div class="live-content"><h1>User management</h1><p>Manage account access without mixing it with research approvals.</p><?php require __DIR__.'/backend/admin_nav.php'; ?><?php if($error): ?><p class="notice error"><?= e($error) ?></p><?php endif; ?><?php foreach($accounts as $account): ?><article class="box"><h2><?= e($account['full_name']) ?></h2><p class="muted"><?= e($account['email']) ?> · <?= e($account['role']) ?> · <?= e($account['department']) ?></p><p><span class="tag"><?= $account['is_active'] ? 'Active' : 'Disabled' ?></span></p><?php if($account['role']!=='admin'): ?><form method="post"><input type="hidden" name="id" value="<?= (int)$account['id'] ?>"><input type="hidden" name="active" value="<?= $account['is_active']?0:1 ?>"><button class="secondary"><?= $account['is_active']?'Disable account':'Enable account' ?></button></form><?php endif; ?></article><?php endforeach; ?></div></main></div></body></html>
